const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={spark:'M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z',book:'M4 4h6c2 0 2 2 2 2s0-2 2-2h6v15h-6c-2 0-2 2-2 2s0-2-2-2H4ZM12 6v15',pen:'m4 16-1 5 5-1L20 8l-4-4ZM14 6l4 4',leaf:'M20 3C9 2 3 8 5 15s13 4 15-12ZM5 20 16 8',people:'M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8ZM2 21v-2a7 7 0 0 1 14 0v2M17 4a4 4 0 0 1 0 8m1 3a5 5 0 0 1 4 5',calendar:'M4 5h16v16H4ZM4 10h16M8 3v4m8-4v4M8 14h1m3 0h1m3 0h1m-9 3h1m3 0h1',chat:'M4 4h16v13H9l-5 4ZM8 9h8m-8 4h5',arrow:'M4 12h16m-6-6 6 6-6 6',refresh:'M20 7v5h-5M4 17v-5h5M6 7a7 7 0 0 1 12-1l2 6M4 12l2 6a7 7 0 0 0 12-1',bookmark:'M6 3h12v18l-6-4-6 4Z',back:'m14 5-7 7 7 7',search:'M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14Zm5-2 6 6',image:'M3 4h18v16H3Zm0 12 5-5 5 5 3-3 5 5M15 8h.01'};
// Small literary marks share a 24-unit drawing grid and keep functional icons separate.
const literaryMarks={
 letterInspiration:'<path d="M5 3.5h11l3 3V21H5Z M16 3.5V7h3"/><path class="literary-ink" d="M8 10c2-2 5-2 7-1-3 0-4 1-5 2 2-1 4 0 5 1-3 0-5 1-7 3 0-2 1-3 3-4-1 0-2 0-3-1Z"/><path class="literary-accent" d="M14.5 17h2v2h-2Z"/>',
 letterConversation:'<path d="M4 8H2.5V3h14v3 M7 6.5h14V21H7Z M10 10h8 M10 13h6 M10 16h4"/><path class="literary-accent" d="M17 17h2v2h-2Z"/>',
 letterReading:'<path d="M12 5.5C9 3.5 5.5 3.2 2.5 4v15c3-.8 6.5-.5 9.5 1.5 3-2 6.5-2.3 9.5-1.5V4c-3-.8-6.5-.5-9.5 1.5Z M12 5.5v15 M5.5 8c1.3-.1 2.5.2 3.5.7 M5.5 11.5c1.3-.1 2.5.2 3.5.7"/><path class="literary-accent" d="M16 4v6l1.5-1 1.5 1V3.7"/>',
 letterWriting:'<path d="m10 12 7.8-9 2.3 2L13 15 M10 12l3 3"/><path class="literary-ink" d="M10 12c-4-.1-4.5 6-7 8 3.3.3 9.2-1.3 10-5-.7-.7-2-2-3-3Z"/><path d="M4.5 22h10"/><path class="literary-accent" d="M17.5 18.5h3v3h-3Z"/>',
 letterCollection:'<path d="m4 3.5 16 .3.5 16.7-17-.3Z M7 7h4v4H7Z M14 7v4h3 M7 14v3h4v-3 M14 14h3v3h-3"/><path class="literary-accent" d="M3.5 20.2h17"/>'
};
const icon=n=>literaryMarks[n]?`<svg class="literary-icon" data-literary-mark="${n}" viewBox="0 0 24 24" aria-hidden="true" focusable="false">${literaryMarks[n]}</svg>`:`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.leaf}"/></svg>`;
const nav=[['inspiration','发现灵感','spark'],['articles','我的文章','book'],['reading','阅读时光','leaf'],['journal','写作记录','calendar']];
const seeds=[];
const readings=[];
if(window.xingzouCloud)readings.splice(0,readings.length,...window.xingzouCloud.catalog);
let storageProblem=false;
function load(key,fallback){if(window.xingzouCloud)return window.xingzouCloud.load(key,fallback);try{const x=localStorage.getItem('xingzou-v1-'+key);return x?JSON.parse(x):fallback}catch{return fallback}}
function persist(key,value){if(window.xingzouCloud)return window.xingzouCloud.persist(key,value);try{localStorage.setItem('xingzou-v1-'+key,JSON.stringify(value));storageProblem=false;return true}catch{storageProblem=true;toast('浏览器存储不可用，请导出文章保留副本');return false}}
let articles=load('articles',[]);
let saved=load('saved',[]),trash=load('trash',[]),activity=load('activity',{}),goal=load('goal',300),favs=load('favs',[]);
let page='inspiration',topic='全部',seedIndex=0,currentId=load('currentId',null),articleFilter='all',query='',customSeed=null,chatMessages=[],fontSize=17,dirty=false,autoTimer;
const dayKey=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const count=s=>s.replace(/\s/g,'').length;
const currentSeed=()=>customSeed||seeds[seedIndex];
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function modal(html){$('#dialog-body').innerHTML=`<div class="modal"><button class="modal-close" data-action="close" aria-label="关闭">×</button>${html}</div>`;if(!$('#dialog').open)$('#dialog').showModal()}
function closeModal(){$('#dialog').close()}
function heading(label,title,desc,action=''){return `<div class="eyebrow">${label}</div><div class="page-heading"><div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function navigate(next,skipSave=false){if(page==='editor'&&!skipSave)saveEditor();page=next;location.hash=next;render()}
function render(){if(!['inspiration','articles','editor','reading','reader','journal'].includes(page))page='articles';document.body.dataset.page=page;document.body.classList.toggle('is-editor',page==='editor');$('#breadcrumb').textContent=nav.find(n=>n[0]===page)?.[1]||(page==='editor'?'我的文章 / 写作':'阅读时光 / 正文');$('#desktop-nav').innerHTML=nav.map(([id,label,i])=>`<button class="nav-link ${page===id?'active':''}" data-page="${id}">${icon(i)}${label}</button>`).join('');$('#mobile-nav').innerHTML=[['inspiration','灵感','spark'],['articles','文章','book'],['reading','阅读','leaf'],['journal','我的','calendar']].map(([id,label,i])=>`<button class="${page===id?'active':''}" data-page="${id}">${icon(i)}${label}</button>`).join('');const views={inspiration:inspirationView,articles:articlesView,editor:editorView,reading:readingView,partners:partnersView,journal:journalView,assistant:assistantView};$('#main').innerHTML=(views[page]||inspirationView)();window.scrollTo(0,0);if(page==='editor')bindEditor();if(page==='journal')bindCalendar()}
function inspirationView(){return '<div class="empty"><h2>正在打开灵感</h2><p>寻找值得停留的文字。</p></div>'}
function seedModal(){toast('正在准备灵感，请稍后再试')}
function nextSeed(){customSeed=null;let options=seeds.filter(x=>topic==='全部'||x.topic===topic);if(options.length<2){options=seeds;topic='全部'}const active=options.findIndex(x=>x.id===seeds[seedIndex].id);seedIndex=seeds.indexOf(options[(active+1)%options.length]);render()}
function createArticle(seed){if(page==='editor')saveEditor();const id=Date.now().toString(36);articles.unshift({id,title:'',content:'',status:'draft',date:dayKey(),seed:seed?seed.short:'',img:seed?.img});currentId=id;persist('currentId',id);persist('articles',articles);closeModal();navigate('editor',true)}
function editorView(){if(!articles.some(a=>a.id===currentId))currentId=articles.find(a=>a.status==='draft')?.id||articles[0]?.id;if(!currentId){const id=Date.now().toString(36);articles.unshift({id,title:'',content:'',date:dayKey(),status:'draft'});currentId=id}const a=articles.find(a=>a.id===currentId);return `<div class="editor-wrap" data-article-id="${esc(a.id)}"><div class="editor-top"><button class="text-btn" data-page="articles">${icon('back')}我的文章</button><span class="save-status" id="save-status">${window.xingzouCloud?esc(window.xingzouCloud.status):'已保存在本机'}</span><div class="actions"><button class="text-btn" data-action="export">导出</button><button class="text-btn" data-action="complete">${a.status==='complete'?'标为草稿':'完成文章'}</button></div></div><input class="editor-title" id="editor-title" aria-label="文章标题" placeholder="标题" value="${esc(a.title)}">${a.seed?`<div class="editor-context"><span>写作起点 · ${esc(a.seed)}</span><button data-action="remove-seed" aria-label="移除灵感提示">×</button></div>`:''}<textarea class="editor-body" id="editor-content" aria-label="文章正文" placeholder="从你记得最清楚的那个细节开始……" style="font-size:${fontSize}px">${esc(a.content)}</textarea><div class="editor-bottom"><div class="actions"><button class="text-btn" data-action="format">Aa 字号</button><button class="text-btn" data-action="editor-ai">${icon('spark')}写作助手</button></div><span id="word-count">${count(a.content)} 字 · 空间内保存</span></div><p class="writing-note">慢慢写。这里没有倒计时。</p></div>`}
function bindEditor(){for(const id of ['#editor-title','#editor-content'])$(id).addEventListener('input',()=>{dirty=true;$('#save-status').textContent='正在保存…';$('#word-count').textContent=`${count($('#editor-content').value)} 字 · 空间内保存`;clearTimeout(autoTimer);autoTimer=setTimeout(saveEditor,450)})}
function saveEditor(){clearTimeout(autoTimer);if(!$('#editor-content'))return;const editorId=$('.editor-wrap')?.dataset.articleId;const a=articles.find(a=>a.id===editorId);if(!a)return;const before=count(a.content);a.title=$('#editor-title').value;a.content=$('#editor-content').value;a.date=dayKey();if(dirty){const log=activity[dayKey()]||{chars:0,edits:0};log.chars+=Math.max(0,count(a.content)-before);log.edits++;activity[dayKey()]=log;persist('activity',activity)}const success=persist('articles',articles);if($('#save-status'))$('#save-status').textContent=success?(window.xingzouCloud?window.xingzouCloud.status:'已保存在本机'):'保存失败，请导出副本';dirty=false}
function articlesView(){const list=articles.filter(a=>(articleFilter==='all'||a.status===articleFilter)&&(a.title+a.content).includes(query));return heading('YOUR WORDS · 文章目录','写过的，都在这里','有些已经成篇，有些还在慢慢长大。',`<button class="primary" data-action="new">＋ 写一篇</button>`)+`<label class="article-search">${icon('search')}<input class="search" id="article-search" aria-label="搜索文章" placeholder="搜索标题或正文" value="${esc(query)}"></label><div class="topic-tabs">${[['all','全部'],['draft','草稿'],['complete','已完成']].map(([k,l])=>`<button class="topic-tab ${articleFilter===k?'active':''}" data-filter="${k}">${l} ${articles.filter(a=>k==='all'||a.status===k).length}</button>`).join('')}</div><div id="article-list">${articleRows(list)}</div>`}
function articleRows(list){return list.length?list.map(a=>`<article class="article-row"><button class="article-open" data-edit="${a.id}"><span class="state-label">${a.status==='draft'?'草稿':'已完成'}</span><h3>${esc(a.title||'尚未命名的一篇')}</h3><p>${esc(a.content||'纸还空着，故事可以从任何地方开始。')}</p><div class="article-meta"><span>${a.date.replaceAll('-',' / ')}</span><span>${count(a.content)} 字</span><span>私密</span></div></button>${a.img?`<img class="article-thumb" src="/assets/${a.img}.jpg" alt="文章配图">`:''}<button class="icon-btn" data-delete="${a.id}" aria-label="将${esc(a.title||'未命名文章')}移入回收站">⋯</button></article>`).join(''):`<div class="empty"><h2>${query?'没有找到这篇文章':'下一篇，从这里开始'}</h2><p>${query?'试试另一个关键词。':'不必准备完美的开头。'}</p><button class="primary" data-action="new">写一篇</button></div>`}
function readingView(){return '<div class="empty"><h2>阅读</h2><p>正在打开内容库。</p></div>'}
function showReading(id){page='reader';const r=readings.find(x=>x.id===id);render();$('#main').innerHTML=`<article class="reader"><button class="text-btn" data-page="reading">${icon('back')}返回阅读</button><h1>${esc(r.title)}</h1><div class="byline">${esc(r.author)} · ${esc(r.category)}</div><img src="/assets/${r.img}.jpg" alt="文章摄影配图"><div class="prose">${r.body.map(x=>`<p>${esc(x)}</p>`).join('')}</div><div class="reader-actions"><button class="text-btn" data-fav="${esc(id)}">${icon('bookmark')}${favs.includes(id)?'已收藏':'收藏文章'}</button><button class="text-btn" data-action="read-reflect">${icon('pen')}写点读后感</button></div></article>`;window.scrollTo(0,0)}
function partnersView(){return '<div class="empty"><h2>写作搭子暂未开放</h2><button class="primary" data-page="articles">回到文章</button></div>'}
function journalView(){const now=new Date(),today=activity[dayKey()]||{chars:0,edits:0};return heading('A WRITING LIFE · 写作记录','日子，一页一页地留下','不用每天写很多，愿意回来就很好。')+`<div class="journal-summary"><div><strong>${Object.keys(activity).length}</strong><small>留下文字的日子</small></div><div><strong>${articles.filter(a=>a.status==='complete').length}</strong><small>已完成的文章</small></div><div><strong>${articles.length}</strong><small>正在积累的篇章</small></div></div><div class="journal-grid"><section><div class="section-heading"><h2>${now.getFullYear()} 年 ${now.getMonth()+1} 月</h2><span>属于你的写作日历</span></div><div class="calendar" id="calendar"></div><div class="journal-day" id="journal-day">今天${today.edits?`进行了 ${today.edits} 次保存，新增 ${today.chars} 字。`:'还没有留下新的文字。写一点，或者改一段，都很好。'}</div></section><section><div class="goal"><div class="eyebrow">今天，给自己一点时间</div><h3>写下 ${goal} 个字</h3><p>已经写了 ${today.chars} 字${today.chars>=goal?'，今天的小目标完成了。':'，不着急，慢慢来。'}</p><div class="progress"><i style="width:${Math.min(100,today.chars/goal*100)}%"></i></div><div class="actions"><button class="text-btn" data-action="new">去写一会儿 →</button><button class="text-btn" data-action="goal">调整目标</button></div></div><div class="settings-links"><button data-page="assistant">AI 写作助手 <span>↗</span></button><button data-action="trash">回收站 <span>${trash.length} 篇 →</span></button><button data-action="export-all">导出所有文章 <span>↓</span></button><button data-action="about">关于笺墨溪 <span>→</span></button></div></section></div>`}
function bindCalendar(){const now=new Date(),first=new Date(now.getFullYear(),now.getMonth(),1).getDay(),days=new Date(now.getFullYear(),now.getMonth()+1,0).getDate();$('#calendar').innerHTML=['日','一','二','三','四','五','六'].map(x=>`<span class="weekday">${x}</span>`).join('')+'<span></span>'.repeat(first)+Array.from({length:days},(_,i)=>{const d=i+1,key=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;return `<button class="${activity[key]?'wrote ':''}${d===now.getDate()?'today':''}" data-day="${key}" aria-label="${key}${activity[key]?' 有写作记录':''}">${d}</button>`}).join('')}
function assistantView(){return '<div class="empty"><h2>和 AI 一起读你的文字</h2><p>打开一篇文章，即可使用写作助手。</p><button class="primary" data-page="articles">选择文章</button></div>'}
function replyChat(){toast('请在文章编辑页使用写作助手')}
function editorAI(){toast('写作助手暂时不可用，请稍后重试')}
function download(name,text,type='text/plain;charset=utf-8'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.addEventListener('click',e=>{const el=e.target.closest('button,a[data-page]');if(!el)return;
 if(el.dataset.action){const action=el.dataset.action;
 if(action==='close')return closeModal();
 if(action==='new')return createArticle();
 if(action==='seed-open')return seedModal();
 if(action==='seed-next')return nextSeed();
 if(action==='seed-next-modal'){nextSeed();return seedModal()}
 if(action==='seed-write')return createArticle(currentSeed());
 if(action==='seed-save'){const s=currentSeed();if(!saved.some(x=>x.id===s.id)){saved.push({...s});persist('saved',saved)}el.textContent='已留到以后';return toast('已保存这条灵感')}
 if(action==='saved')return modal(`<div class="eyebrow">留到以后</div><h2>还没写下的念头</h2>${saved.length?saved.map(s=>`<button class="saved-item" data-saved="${s.id}">${esc(s.short)} ↗</button>`).join(''):'<p>遇到喜欢的灵感，点“留到以后”，它就会出现在这里。</p>'}`);
 if(action==='remove-seed'){saveEditor();articles.find(a=>a.id===currentId).seed='';persist('articles',articles);return render()}
 if(action==='format'){fontSize=fontSize===17?19:fontSize===19?21:17;$('#editor-content').style.fontSize=fontSize+'px';return toast(`正文字号：${fontSize}`)}
 if(action==='export'){saveEditor();const a=articles.find(x=>x.id===currentId);download((a.title||'未命名文章')+'.txt',a.title+'\n\n'+a.content);return toast('已导出文章副本')}
 if(action==='export-all'){saveEditor();download('笺墨溪-完整备份.json',JSON.stringify({format:'xingzou-v1',state:{articles,trash,saved,favs,activity,goal,currentId}},null,2),'application/json');return toast('已导出文章与收藏备份')}
 if(action==='complete'){saveEditor();const a=articles.find(x=>x.id===currentId);if(!a.content.trim())return toast('先写一点内容，再完成这篇文章');a.status=a.status==='complete'?'draft':'complete';persist('articles',articles);render();return toast(a.status==='complete'?'这篇文章完成了':'已放回草稿')}
 if(action==='editor-ai')return editorAI();
 if(action==='undo-draft'){const a=articles.find(x=>x.id===currentId);if(a.undoContent!==undefined){a.content=a.undoContent;delete a.undoContent;persist('articles',articles)}closeModal();render();return toast('已撤销插入')}
 if(action==='read-reflect')return createArticle({short:'阅读之后，我想起了……'});
 if(action==='goal')return modal(`<div class="eyebrow">给自己一个小目标</div><h2>今天，想写多少？</h2><p>可以随时调整。完成一段修改，也是一种前进。</p><input class="modal-input" type="number" min="50" max="10000" step="50" id="goal-input" aria-label="每日字数目标" value="${goal}"><button class="primary" data-action="save-goal">保存目标</button>`);
 if(action==='save-goal'){const value=Number($('#goal-input').value);if(!Number.isFinite(value)||value<50||value>10000)return toast('请输入 50 到 10000 之间的字数');goal=Math.round(value);persist('goal',goal);closeModal();return render()}
 if(action==='trash')return modal(`<div class="eyebrow">回收站</div><h2>暂时收起的文章</h2>${trash.length?trash.map(a=>`<button class="saved-item" data-restore="${a.id}">${esc(a.title||'未命名文章')} <small style="font:11px var(--sans);margin-top:8px;color:var(--muted)">点击恢复 →</small></button>`).join(''):'<p>这里还没有文章。删除的文章会先保留在这里。</p>'}`);
 if(action==='about')return modal('<div class="eyebrow">关于笺墨溪</div><h2>把生活写下来</h2><p>阅读、记录，与文字相处。</p>');
 }
 if(el.dataset.page)return navigate(el.dataset.page);
 if(el.dataset.topic){topic=el.dataset.topic;customSeed=null;seedIndex=topic==='全部'?0:seeds.findIndex(x=>x.topic===topic);return render()}
 if(el.dataset.seed){customSeed=null;seedIndex=seeds.findIndex(x=>x.id===el.dataset.seed);return seedModal()}
 if(el.dataset.saved){customSeed=saved.find(x=>x.id===el.dataset.saved);return seedModal()}
 if(el.dataset.edit){if(!articles.some(a=>a.id===el.dataset.edit))return toast('这篇文章已移入回收站');if(page==='editor')saveEditor();currentId=el.dataset.edit;persist('currentId',currentId);closeModal();return navigate('editor',true)}
 if(el.dataset.filter){articleFilter=el.dataset.filter;return render()}
 if(el.dataset.delete){const a=articles.find(x=>x.id===el.dataset.delete);return modal(`<div class="eyebrow">管理文章</div><h2>${esc(a.title||'未命名文章')}</h2><p>移入回收站后，仍可在“我的 → 回收站”恢复。</p><div class="actions"><button class="secondary" data-confirm-delete="${a.id}">移入回收站</button><button class="primary" data-action="close">保留文章</button></div>`)}
 if(el.dataset.confirmDelete){const id=el.dataset.confirmDelete;trash.push(articles.find(x=>x.id===id));articles=articles.filter(x=>x.id!==id);persist('articles',articles);persist('trash',trash);closeModal();render();return toast('文章已移入回收站')}
 if(el.dataset.restore){const id=el.dataset.restore;articles.unshift(trash.find(x=>x.id===id));trash=trash.filter(x=>x.id!==id);persist('articles',articles);persist('trash',trash);closeModal();render();return toast('文章已恢复')}
 if(el.dataset.read)return showReading(el.dataset.read);
 if(el.dataset.fav){const id=el.dataset.fav;favs=favs.includes(id)?favs.filter(x=>x!==id):[...favs,id];persist('favs',favs);el.innerHTML=icon('bookmark')+(favs.includes(id)?'已收藏':'收藏文章');return toast(favs.includes(id)?'已收藏这篇文章':'已取消收藏')}
 if(el.dataset.day){document.querySelectorAll('[data-day]').forEach(x=>x.classList.remove('selected'));el.classList.add('selected');const log=activity[el.dataset.day];$('#journal-day').textContent=el.dataset.day+' · '+(log?`进行了 ${log.edits} 次保存，新增 ${log.chars} 字。`:'这天还没有写作记录。');return}
 if(el.dataset.chatPrompt)return replyChat(el.dataset.chatPrompt);
});
document.addEventListener('input',e=>{if(e.target.id==='article-search'){query=e.target.value;$('#article-list').innerHTML=articleRows(articles.filter(a=>(articleFilter==='all'||a.status===articleFilter)&&(a.title+a.content).includes(query)))}});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=$('#dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1)||'inspiration';if(document.documentElement.classList.contains('web-cloud')&&!['inspiration','articles','editor','reading','reader','journal'].includes(next))return;if(next!==page){if(page==='editor')saveEditor();page=next;render();if(page==='reader'&&typeof renderWork==='function'&&openedWork)renderWork()}});
window.addEventListener('pagehide',saveEditor);
document.addEventListener('visibilitychange',()=>{if(document.hidden)saveEditor()});
page=(nav.some(n=>n[0]===location.hash.slice(1))||location.hash==='#editor')?location.hash.slice(1):location.hash==='#reader'?'reading':'inspiration';render();
